import{_ as s,o as a,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"案例 08 · 蜜雪冰城 × 可灵「意想不到雪王」（逆向拆解）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"cases/case-08-mixue-kling.md","filePath":"cases/case-08-mixue-kling.md","lastUpdated":1786286917000}'),e={name:"cases/case-08-mixue-kling.md"};function n(d,t,l,p,i,h){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="案例-08-·-蜜雪冰城-×-可灵「意想不到雪王」-逆向拆解" tabindex="-1">案例 08 · 蜜雪冰城 × 可灵「意想不到雪王」（逆向拆解） <a class="header-anchor" href="#案例-08-·-蜜雪冰城-×-可灵「意想不到雪王」-逆向拆解" aria-label="Permalink to &quot;案例 08 · 蜜雪冰城 × 可灵「意想不到雪王」（逆向拆解）&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：品牌交付的不是一支片子，而是<strong>一个让用户自己生产片子的工具</strong>——这是 <a href="/method/ad-formats">片型图谱</a> 十一种片型之外的物种。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">先说清楚这篇的性质</p><p>这是对<strong>公开营销活动的逆向拆解</strong>，不是项目复盘。</p><ul><li>信息来源为行业媒体报道与平台公开信息，<strong>未参与项目</strong>，也未获取任何制作记录。</li><li>传播数据为<strong>平台 / 品牌方对外口径</strong>，未经第三方核实。曝光量类指标通常口径宽松，见 ③。</li><li>涉及的品牌形象、IP 与平台名称仅用于指称分析对象，权利归各自权利人所有。</li></ul></div><div class="danger custom-block"><p class="custom-block-title">时间说明</p><p>活动时间为 <strong>2025 年 8 月</strong>，<strong>不是最新案例</strong>。</p><p>之所以仍然值得单开一篇：<strong>它是本站收录的案例里唯一一个「产出物不是广告片」的</strong>。这个形态上的差异，比时间新旧重要得多。</p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>现制茶饮</td></tr><tr><td>交付形态</td><td><strong>AI 特效模板</strong>（不是广告片）</td></tr><tr><td>投放渠道</td><td>快手</td></tr><tr><td>生成引擎</td><td>可灵 AI</td></tr><tr><td>参与形式</td><td>用户上传照片 → 自动生成雪王入镜的短视频</td></tr><tr><td>传播</td><td>话题曝光 10 亿+、社交互动 77.1 万（口径）</td></tr></tbody></table><hr><h2 id="_1-它的产出物是什么" tabindex="-1">① 它的产出物是什么 <a class="header-anchor" href="#_1-它的产出物是什么" aria-label="Permalink to &quot;① 它的产出物是什么&quot;">​</a></h2><p>先把形态说清楚，因为这决定了后面所有分析。</p><p><strong>普通广告的交付链条</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>品牌 → 创意 → 制作 → 一支片子 → 投放 → 用户观看</span></span></code></pre></div><p><strong>这个案例的交付链条</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>品牌 → 创意 → 制作 → 一个特效模板 → 用户使用 → N 支片子 → 用户自己传播</span></span></code></pre></div><p>用户上传一张自己的照片，AI「理解」照片里的场景，自动把雪王合成进去，生成一段个性化的小剧情——雪王和用户的宠物互动、雪王出现在用户的旅行照里。</p><div class="tip custom-block"><p class="custom-block-title">差别不在技术，在交付物的位置</p><p>品牌做完的那一刻，<strong>片子还不存在</strong>。</p><p>它做完的是<strong>生产片子的能力</strong>，内容由用户填。这与所有传统片型的根本区别在于：<strong>创意的最后一公里交给了用户</strong>，而品牌控制的是那个&quot;容器&quot;。</p></div><hr><h2 id="_2-为什么这个玩法能成立-一个技术前提" tabindex="-1">② 为什么这个玩法能成立：一个技术前提 <a class="header-anchor" href="#_2-为什么这个玩法能成立-一个技术前提" aria-label="Permalink to &quot;② 为什么这个玩法能成立：一个技术前提&quot;">​</a></h2><p>这是本篇最值得记的一条，<strong>而且它是技术判断，不是营销判断</strong>。</p><p>这套玩法的核心技术难点是：<strong>在成千上万张完全不可控的用户照片里，把同一个品牌形象合成进去，还得每次都长得一样。</strong></p><p>按 <a href="/method/brand-consistency">品牌一致性控制</a> 的分析，这是 AI 最容易翻车的地方。<strong>那它为什么能成？</strong></p><p>因为雪王这个 IP 恰好具备三个特征：</p><table tabindex="0"><thead><tr><th>特征</th><th>为什么关键</th></tr></thead><tbody><tr><td><strong>卡通形象</strong></td><td>没有真人的微表情和口型问题——<a href="/prompts/spokesperson">AI 目前最弱的一环</a>直接绕过</td></tr><tr><td><strong>造型极简</strong></td><td>白色胖身体 + 王冠 + 权杖。<strong>结构越简单，AI 画错的余地越小</strong></td></tr><tr><td><strong>辨识度极高</strong></td><td>就算比例略有偏差，观众也一眼认得出。<strong>容错率高</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这条前提决定了谁能抄、谁不能抄</p><p>把雪王换成下面任何一个，这套玩法立刻崩掉：</p><table tabindex="0"><thead><tr><th>换成</th><th>会发生什么</th></tr></thead><tbody><tr><td>真人代言人</td><td>脸崩、表情僵硬，观众一眼出戏</td></tr><tr><td>有 logo 的实体产品</td><td>logo 变形、包装文字乱码——<a href="/tools/landscape">所有图像工具的共同短板</a></td></tr><tr><td>结构复杂的吉祥物</td><td>细节越多，跨次生成的漂移越明显</td></tr></tbody></table><p><strong>结论：这个案例的可复制性，取决于你的品牌有没有一个「简单到 AI 画不坏」的视觉符号。</strong></p><p>绝大多数品牌没有。<strong>所以这篇拆解的价值，一半在于说清楚「你大概率抄不了」。</strong></p></div><hr><h2 id="_3-传播数据怎么看" tabindex="-1">③ 传播数据怎么看 <a class="header-anchor" href="#_3-传播数据怎么看" aria-label="Permalink to &quot;③ 传播数据怎么看&quot;">​</a></h2><p>公开口径：话题曝光 10 亿+，社交互动 77.1 万，话题登上平台热榜。同期该 IP 在另一平台的共创计划也公布了 7 天 12 万+ UGC 作品的数据。</p><div class="danger custom-block"><p class="custom-block-title">曝光量是最不该直接引用的指标</p><p><strong>一、口径极宽。</strong>「话题曝光」通常统计的是话题页的浏览总量，包含大量非目标人群的滑过。10 亿这个量级，和「10 亿人看了广告」完全是两回事。</p><p>**二、互动率才是真信号。**曝光 10 亿 / 互动 77.1 万，<strong>互动率约 0.077%</strong>。这个数字本身不难看（话题类活动的常见区间），但它说明：<strong>绝大多数曝光是路过，不是参与。</strong></p><p>**三、UGC 作品数是这类活动最硬的指标。**因为它需要用户完成「上传照片 → 等待生成 → 发布」的完整动作，注水难度远高于浏览量。<strong>看这类案例时，优先找作品数，其次找互动数，最后才看曝光。</strong></p></div><hr><h2 id="_4-三层结构-谁出了什么" tabindex="-1">④ 三层结构：谁出了什么 <a class="header-anchor" href="#_4-三层结构-谁出了什么" aria-label="Permalink to &quot;④ 三层结构：谁出了什么&quot;">​</a></h2><p>这个玩法能跑起来，靠的是三方各出一块，缺一不可：</p><table tabindex="0"><thead><tr><th>角色</th><th>出什么</th><th>换个说法</th></tr></thead><tbody><tr><td><strong>品牌</strong></td><td>IP 形象、创意规则、活动预算</td><td>出「主角」</td></tr><tr><td><strong>平台 / 工具方</strong></td><td>生成能力、特效入口、流量位</td><td>出「机器」</td></tr><tr><td><strong>用户</strong></td><td>素材（自己的照片）、创意（怎么玩）、传播</td><td>出「内容和嗓门」</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">品牌真正让渡的东西</p><p><strong>是创意控制权。</strong></p><p>传统广告里，画面每一帧都是品牌审过的。这个玩法里，用户拿雪王去干什么，品牌事先不知道。</p><p>这是<strong>用可控性换参与度</strong>——一笔明确的交易，做之前要想清楚愿不愿意换。</p></div><hr><h2 id="_5-这类玩法独有的风险" tabindex="-1">⑤ 这类玩法独有的风险 <a class="header-anchor" href="#_5-这类玩法独有的风险" aria-label="Permalink to &quot;⑤ 这类玩法独有的风险&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">用户生成的内容挂在你的品牌名下</p><p>这是普通广告完全没有的风险类型：</p><ol><li><strong>不当内容</strong>。用户可能上传不适宜的照片，生成的内容仍带着你的品牌形象和话题标签。</li><li><strong>形象损伤</strong>。IP 被用于品牌不希望关联的语境，事后难以撤回。</li><li><strong>肖像与隐私</strong>。用户上传的照片里可能有他人肖像。<strong>授权链条是否清晰，是活动上线前必须与平台确认的事项</strong>，参见 <a href="/prompts/spokesperson">人物代言的边界</a>。</li><li><strong>审核成本</strong>。作品量越大，人工审核越不可能覆盖。<strong>「12 万+ 作品」意味着人工是看不完的。</strong></li></ol><p><strong>开放共创的活动，风控预案必须在上线前做好，不能等出事再补。</strong></p></div><hr><h2 id="_6-可复用套路" tabindex="-1">⑥ 可复用套路 <a class="header-anchor" href="#_6-可复用套路" aria-label="Permalink to &quot;⑥ 可复用套路&quot;">​</a></h2><ol><li><p>**先看自己有没有「AI 画不坏」的视觉符号。**卡通、简单、高辨识度——三条缺一条，这个玩法的成功率就大幅下降。</p></li><li><p><strong>产出物可以不是片子。</strong>「做一支广告」和「做一个让用户做广告的工具」是两条不同的路。后者省的不是制作费，是<strong>传播费</strong>——用户替你分发。</p></li><li><p>**看这类案例的数据，先找 UGC 作品数。**曝光量口径最宽，作品数最难注水。</p></li><li><p>**用可控性换参与度，是笔要算清的交易。**品牌调性严肃、法务尺度紧的品类，这笔交易多半不划算。</p></li><li><p>**风控预案要在上线前做。**作品量一大，人工审核就失效了。</p></li></ol><hr><h2 id="对本站片型图谱的影响" tabindex="-1">对本站片型图谱的影响 <a class="header-anchor" href="#对本站片型图谱的影响" aria-label="Permalink to &quot;对本站片型图谱的影响&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">需要新增一个维度</p><p><a href="/method/ad-formats">片型图谱</a> 现在的十一种片型，<strong>全部假设「品牌产出的是内容」</strong>。</p><p>这个案例说明还有另一类：<strong>品牌产出的是生产内容的工具。</strong></p><p>这不是第十二种片型——<strong>它和那十一种不在同一个层级上</strong>，是一个更前置的分叉：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>品牌要交付什么？</span></span>
<span class="line"><span>├── 内容 ──→ 走片型图谱的十一种</span></span>
<span class="line"><span>└── 工具 ──→ 特效模板、共创玩法（本案例）</span></span></code></pre></div><p>这个分叉应该加在片型图谱的最前面，<strong>在「选片型」之前先问「做内容还是做工具」</strong>。</p><p><strong>暂不改动那一页</strong>——这个判断目前只有一个案例支撑，等再看到两三个同类案例，确认它是一个稳定的类别而不是偶发玩法，再动结构。</p></div><hr><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本文的观察</th><th>对应的方法</th></tr></thead><tbody><tr><td>简单卡通形象才扛得住批量合成</td><td><a href="/method/brand-consistency">品牌一致性控制</a></td></tr><tr><td>真人和复杂产品为什么不行</td><td><a href="/prompts/spokesperson">人物代言</a>、<a href="/tools/landscape">全景对照表 · 图像工具的共同短板</a></td></tr><tr><td>品牌产出内容 vs 产出工具</td><td><a href="/method/ad-formats">片型图谱</a></td></tr><tr><td>UGC 风格的合规边界</td><td><a href="/prompts/ugc-style">UGC 仿真风</a></td></tr><tr><td>效率与效果数字怎么看</td><td><a href="/cases/case-07-yuanqi-fenzhong">案例 07 · 元气森林 × 分众</a></td></tr></tbody></table><p><strong>参考来源</strong>：<a href="https://www.aitop100.cn/infomation/details/28493.html" target="_blank" rel="noreferrer">意想不到的雪王 AIGC 创作大赛 · AITOP100</a> · <a href="https://www.sohu.com/a/981322590_122532322" target="_blank" rel="noreferrer">AI 统治营销圈？20 个案例 · 搜狐</a> · <a href="https://36kr.com/p/3054334861447558" target="_blank" rel="noreferrer">没想到，蜜雪冰城都要搞 AI 了 · 36氪</a></p>`,44)])])}const b=s(e,[["render",n]]);export{c as __pageData,b as default};
